(70, 36, '_form', '<div id=\"contact-form\">\n\n      					<fieldset>\n\n                        <div class=\"half\">\n      						   <label>ФИО <span class=\"required\">*</span></label>\n      						   [text* your-name]\n                        </div>\n\n                        <div class=\"half pull-right\">\n      						   <label>Возраст<span class=\"required\">*</span></label>\n      						   [text* age]\n                        </div>\n\n                        <div class=\"half\">\n      						   <label>Город проживания <span class=\"required\">*</span></label>\n      						   [text* city]\n                        </div>\n\n                        <div class=\"half pull-right\">\n      						   <label>Телефон <span class=\"required\">*</span></label>\n      						   [tel* tel]\n                        </div>\n\n                        <div>\n      						   <label>Email <span class=\"required\">*</span></label>\n      						   [email* email]\n                        </div>\n\n                        <div>\n                           <label  for=\"contactMessage\">О себе <span class=\"required\">*</span></label>\n                           [textarea* about]\n                        </div>\n\n                        <div>\n                           [submit \"Отправить\"]\n                           <span id=\"image-loader\">\n                              <img src=\"images/loader.gif\" alt=\"\" />\n                           </span>\n                        </div>\n\n      					</fieldset>\n\n                  <!-- contact-warning -->\n                  <div id=\"message-warning\"></div>\n                  <!-- contact-success -->\n      				<div id=\"message-success\">\n                     <i class=\"icon-ok\"></i>Your message was sent, thank you!<br />\n      				</div>\n\n               </div>'),
(71, 36, '_mail', 'a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:30:\"[_site_title] \"[your-subject]\"\";s:6:\"sender\";s:7:\"[email]\";s:9:\"recipient\";s:23:\"<teatrkukoludm@mail.ru>\";s:4:\"body\";s:163:\"From: [your-name] <[your-email]>\nSubject: [your-subject]\n\nMessage Body:\n[your-message]\n\n-- \nThis e-mail was sent from a contact form on [_site_title] ([_site_url])\";s:18:\"additional_headers\";s:0:\"\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),
(72, 36, '_mail_2', 'a:9:{s:6:\"active\";b:0;s:7:\"subject\";s:30:\"[_site_title] \"[your-subject]\"\";s:6:\"sender\";s:28:\"[_site_title] <wordpress@m4>\";s:9:\"recipient\";s:12:\"[your-email]\";s:4:\"body\";s:105:\"Message Body:\n[your-message]\n\n-- \nThis e-mail was sent from a contact form on [_site_title] ([_site_url])\";s:18:\"additional_headers\";s:29:\"Reply-To: [_site_admin_email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),
(73, 36, '_messages', 'a:22:{s:12:\"mail_sent_ok\";s:45:\"Thank you for your message. It has been sent.\";s:12:\"mail_sent_ng\";s:71:\"There was an error trying to send your message. Please try again later.\";s:16:\"validation_error\";s:61:\"One or more fields have an error. Please check and try again.\";s:4:\"spam\";s:71:\"There was an error trying to send your message. Please try again later.\";s:12:\"accept_terms\";s:69:\"You must accept the terms and conditions before sending your message.\";s:16:\"invalid_required\";s:22:\"The field is required.\";s:16:\"invalid_too_long\";s:22:\"The field is too long.\";s:17:\"invalid_too_short\";s:23:\"The field is too short.\";s:13:\"upload_failed\";s:46:\"There was an unknown error uploading the file.\";s:24:\"upload_file_type_invalid\";s:49:\"You are not allowed to upload files of this type.\";s:21:\"upload_file_too_large\";s:20:\"The file is too big.\";s:23:\"upload_failed_php_error\";s:38:\"There was an error uploading the file.\";s:12:\"invalid_date\";s:45:\"Формат даты некорректен.\";s:14:\"date_too_early\";s:74:\"Введённая дата слишком далеко в прошлом.\";s:13:\"date_too_late\";s:74:\"Введённая дата слишком далеко в будущем.\";s:14:\"invalid_number\";s:47:\"Формат числа некорректен.\";s:16:\"number_too_small\";s:68:\"Число меньше минимально допустимого.\";s:16:\"number_too_large\";s:70:\"Число больше максимально допустимого.\";s:23:\"quiz_answer_not_correct\";s:69:\"Неверный ответ на проверочный вопрос.\";s:13:\"invalid_email\";s:62:\"Неверно введён электронный адрес.\";s:11:\"invalid_url\";s:53:\"Введён некорректный URL адрес.\";s:11:\"invalid_tel\";s:70:\"Введён некорректный телефонный номер.\";}'),
