(12, 1, '2022-02-08 12:48:37', '2022-02-08 09:48:37', '<!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"has-text-align-center\" id=\"услуги\">Услуги</h1>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"id\":41,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://m4/wp-content/uploads/2022/02/2-1024x682.jpg\" alt=\"\" class=\"wp-image-41\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 id=\"творческая-встреча\">Творческая встреча</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Знакомство с актером, художником, режиссером и куклами. Узнаете об истории театра и попробуете себя в роли кукловода!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><li>Группы – от 10 человек</li><li>Продолжительность: 40–50 минут</li><li>Возраст: от 7 лет</li><li>Стоимость: 100 рублей</li></ul>\n<!-- /wp:list -->\n\n<!-- wp:image {\"id\":40,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://m4/wp-content/uploads/2022/02/3-1.jpg\" alt=\"\" class=\"wp-image-40\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 id=\"творческая-встреча\">Экскурсия по цехам</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Знакомство с работой некоторых цехов Театра. Погружение в тайны мастерства кукольников и секреты закулисья.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><li>Группа – до 10 человек</li><li>Возраст: от 10 лет</li><li>Стоимость: 150 рублей</li></ul>\n<!-- /wp:list -->\n\n<!-- wp:image {\"id\":39,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://m4/wp-content/uploads/2022/02/3.jpg\" alt=\"\" class=\"wp-image-39\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"left\"} -->\n<h2 class=\"has-text-align-left\" id=\"творческая-встреча-с-экскурсией\">Творческая встреча с экскурсией</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Встреча с актером и куклами, знакомство с работой цехов Театра, тайны мастерства кукольников и секреты закулисья.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><li>Группа – до 10 человек</li><li>Продолжительность: 1–1,5 часа</li><li>Возраст: от 10 лет</li><li>Стоимость: 250 рублей</li></ul>\n<!-- /wp:list -->', 'Услуги', '', 'publish', 'closed', 'closed', '', '%d1%83%d1%81%d0%bb%d1%83%d0%b3%d0%b8', '', '', '2022-02-08 14:35:23', '2022-02-08 11:35:23', '', 0, 'http://m4/?page_id=12', 0, 'page', '', 0),
