(14, 1, '2022-02-08 12:48:47', '2022-02-08 09:48:47', '<!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"has-text-align-center\" id=\"наши-проекты\">Наши проекты</h1>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"id\":41,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://m4/wp-content/uploads/2022/02/2-1024x682.jpg\" alt=\"\" class=\"wp-image-41\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 id=\"тук-лаб\">ТУК-Лаб</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Театральная лаборатория молодых режиссеров и художников. Приглашаем молодых режиссеров и художников к участию в Театральной лаборатории</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:html -->\n<button class=\"submit\">Участвовать</button>\n<!-- /wp:html -->', 'Наши проекты', '', 'publish', 'closed', 'closed', '', '%d0%bd%d0%b0%d1%88%d0%b8-%d0%bf%d1%80%d0%be%d0%b5%d0%ba%d1%82%d1%8b', '', '', '2022-02-08 14:39:16', '2022-02-08 11:39:16', '', 0, 'http://m4/?page_id=14', 0, 'page', '', 0),
